from collections import deque
from typing import List

class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        # Build initial graph with consecutive roads
        graph = [[] for _ in range(n)]
        for i in range(n - 1):
            graph[i].append(i + 1)

        result = []

        for u, v in queries:
            # Add the new road from u to v
            graph[u].append(v)

            # Find shortest path from 0 to n-1 using BFS
            visited = [False] * n
            queue = deque([(0, 0)])  # (city, distance)
            visited[0] = True

            while queue:
                city, dist = queue.popleft()

                if city == n - 1:
                    result.append(dist)
                    break

                for neighbor in graph[city]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append((neighbor, dist + 1))

        return result

class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0 (top-left corner)
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Convert final row and column back to linear position
        return row * n + col

class Solution:
    def countOfPairs(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)

        # dp[i][val] = number of ways to assign arr1[0...i] such that arr1[i] = val
        # We'll use a dictionary to store the state

        # Initialize for position 0
        dp = {}
        for val in range(nums[0] + 1):
            dp[val] = 1

        # Process each position from 1 to n-1
        for i in range(1, n):
            new_dp = {}

            # For each possible value of arr1[i-1]
            for prev_val, count in dp.items():
                # arr1[i] must be >= prev_val (non-decreasing)
                # arr1[i] must be >= prev_val + (nums[i-1] - nums[i]) (from arr2 non-increasing)
                min_val = max(prev_val, prev_val + (nums[i-1] - nums[i]))

                # arr1[i] must be <= nums[i] (since arr2[i] >= 0)
                max_val = nums[i]

                # If no valid range, skip
                if min_val > max_val:
                    continue

                # Add all valid values of arr1[i]
                for curr_val in range(min_val, max_val + 1):
                    new_dp[curr_val] = (new_dp.get(curr_val, 0) + count) % MOD

            dp = new_dp

        # Sum all possibilities for the last position
        result = 0
        for count in dp.values():
            result = (result + count) % MOD

        return result

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Count balls by player and color
        player_color_count = {}

        for player, color in pick:
            if player not in player_color_count:
                player_color_count[player] = {}
            player_color_count[player][color] = player_color_count[player].get(color, 0) + 1

        # Count winning players
        winning_count = 0

        for player in range(n):
            if player not in player_color_count:
                # Player picked no balls
                continue

            # Find maximum count of any single color for this player
            max_count = max(player_color_count[player].values())

            # Player i wins if they have at least (i+1) balls of the same color
            if max_count >= player + 1:
                winning_count += 1

        return winning_count

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate minimum flips needed to make all rows palindromic
        rows_flips = 0
        for i in range(m):
            # For each row, check symmetric pairs
            for j in range(n // 2):
                # Compare position j with position (n-1-j)
                if grid[i][j] != grid[i][n - 1 - j]:
                    rows_flips += 1

        # Calculate minimum flips needed to make all columns palindromic
        cols_flips = 0
        for j in range(n):
            # For each column, check symmetric pairs
            for i in range(m // 2):
                # Compare position i with position (m-1-i)
                if grid[i][j] != grid[m - 1 - i][j]:
                    cols_flips += 1

        # Return the minimum of the two options
        return min(rows_flips, cols_flips)

